{"frozen_reasoning_spans":[{"end":105,"id":"S001","sha256":"45c0a21c310b61358afedd47fc99017ba5d51b0e9c55d2880e6f1d7d73517dfe","start":0,"text":"To solve the equation |x + 9| = 4x + 86, we consider two cases based on the definition of absolute value."},{"end":152,"id":"S002","sha256":"e40fd6aca2b2482ccfb41acd8b382a6ad6564b0932e287cf332960e2d4cac36a","start":106,"text":"Case 1: x + 9 \u2265 0, which simplifies to x \u2265 -9."},{"end":183,"id":"S003","sha256":"38734f606c2e76e7b35e131dcc59e740c5198aef41ee0095808161310b3cf538","start":153,"text":"In this case, |x + 9| = x + 9."},{"end":214,"id":"S004","sha256":"d7a0dece332de8451910bc892327c47c62411d0d208f656bd0f815639aba2808","start":184,"text":"Thus, we have x + 9 = 4x + 86."},{"end":243,"id":"S005","sha256":"6243daca21e01a148146d16def11c3e3ab333917bbbaa8a8958549bfed3c0b43","start":215,"text":"Solving for x gives x = -23."},{"end":315,"id":"S006","sha256":"955443fa84c132ea219e3d99cc87b40a37289126adb26bbcfee8c02e59bd186f","start":244,"text":"However, we must check if this solution satisfies the condition x \u2265 -9."},{"end":357,"id":"S007","sha256":"ba395ea3128c5fec8699817591cf8e94bb17373b9f3c45168b8cf87b419f4d4b","start":316,"text":"Since -23 < -9, this solution is invalid."},{"end":404,"id":"S008","sha256":"405bc66d55c85a32edf45b7301c140490e8266af2dc5e267ff665f2bdac9f60c","start":358,"text":"Case 2: x + 9 < 0, which simplifies to x < -9."},{"end":447,"id":"S009","sha256":"2eaf4d2fe525fda65b304f165acc23693c0ee40d0d0e65ce5bcbf4e70505ae9f","start":405,"text":"In this case, |x + 9| = -(x + 9) = -x - 9."},{"end":479,"id":"S010","sha256":"fb09a1b1960e68a6a0a68bebf7a809ff148a2015da52a25d00317f0ae0466e20","start":448,"text":"Thus, we have -x - 9 = 4x + 86."},{"end":508,"id":"S011","sha256":"ffcac4c743eb4360ba3899e8699df243e0fee4e58219dc087efa3cb12d829e1c","start":480,"text":"Solving for x gives x = -25."},{"end":571,"id":"S012","sha256":"f11220476945ae80dd1b2de09bb9f3003d45d9a638d06ede32092634e76d4328","start":509,"text":"We must check if this solution satisfies the condition x < -9."},{"end":611,"id":"S013","sha256":"1776abb0f7cb413b8fc7db8a1142033cab8ad927a0b98758ff87760a85e62f6e","start":572,"text":"Since -25 < -9, this solution is valid."},{"end":663,"id":"S014","sha256":"e0a9805bf96a56721e10b522384d529ae84eb2116025506bcbf89fcc696688b7","start":612,"text":"Therefore, the solution to the equation is x = -25."}],"problem":"Solve for x: |x + 9| = 4x + 86. Report the value of x.","problem_id":"cw1-6859921b4cde","span_projection_version":"action-census-reasoning-span-projection-v1"}

